import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    try:
        N = int(data[0])
    except:
        return
    lines = []
    for i in range(1, N + 1):
        if i == N:
            lines.append(str(i))
        else:
            spaces = 2 * (N - i) - 1
            lines.append(str(i) + ' ' * spaces + str(i))
    for i in range(N - 1, 0, -1):
        spaces = 2 * (N - i) - 1
        lines.append(str(i) + ' ' * spaces + str(i))
    sys.stdout.write('\n'.join(lines))

if __name__ == "__main__":
    solve()
